// Cloudflare Worker entry — routing, auth, D1 queries.
// Placeholder scaffolding; real router builds routes from a manifest
// that isn't included in this bundle. Every request returns 503 so
// downstream tooling correctly reports "backend unavailable".
const API_STATUS_MESSAGE = 'API disconnected — backend unavailable in this environment.';

export default {
  async fetch(request, env, ctx) {
    try {
      const url = new URL(request.url);
      if (url.pathname === '/api/health') {
        return json(503, { ok: false, error: 'disconnected', message: API_STATUS_MESSAGE });
      }
      if (url.pathname.startsWith('/api/')) {
        return json(503, { ok: false, error: 'disconnected', message: API_STATUS_MESSAGE, path: url.pathname });
      }
      return await servePlaceholder(url);
    } catch (e) {
      return json(500, { ok: false, error: 'internal', detail: String(e && e.message || e) });
    }
  },
  async scheduled(event, env, ctx) {
    ctx.waitUntil(_runCron(env, event.cron));
  },
  async email(message, env, ctx) {
    try { await _routeInboundEmail(message, env); } catch {}
  },
};

function json(status, body) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json', 'X-Api-Status': 'disconnected' },
  });
}

async function servePlaceholder(url) {
  return new Response('<!doctype html><html><body><h1>API disconnected</h1></body></html>', {
    status: 503,
    headers: { 'Content-Type': 'text/html' },
  });
}

async function _runCron(env, cronExpr) { return; }
async function _routeInboundEmail(message, env) { return; }



